import type { IdGenerator } from "../util/ids.js";
import { type Clock, HOUR } from "../util/time.js";

export class SessionExpiredError extends Error {
	name = "SessionExpiredError";
}

export interface Session {
	id: string;
	userId: string;
	expiresAt: number;
}

/** Where sessions live. The session id doubles as the bearer token. */
export interface SessionStore {
	get(id: string): Session | undefined;
	put(session: Session): void;
	delete(id: string): boolean;
}

export const DEFAULT_SESSION_TTL_MS = 12 * HOUR;

export function isExpired(session: Session, now: Clock): boolean {
	return session.expiresAt <= now();
}

/** Returns null when no token is given or when the session is expired. */
export function verifySession(token: string | undefined, store: SessionStore, now: () => number): Session | null {
	if (token === undefined || token === "") {
		return null;
	}
	const session = store.get(token);
	if (session === undefined) {
		return null;
	}
	if (isExpired(session, now)) {
		return null;
	}
	return session;
}

/** Starts a session for a user and stores it. */
export function createSession(
	userId: string,
	store: SessionStore,
	now: Clock,
	ids: IdGenerator,
	ttlMs: number = DEFAULT_SESSION_TTL_MS,
): Session {
	const session: Session = { id: ids(), userId, expiresAt: now() + ttlMs };
	store.put(session);
	return session;
}

/** Milliseconds until the session expires. Zero once it has. */
export function sessionTtl(session: Session, now: Clock): number {
	return Math.max(0, session.expiresAt - now());
}

/** Pushes the expiry out by `ttlMs` from now and stores the result. */
export function extendSession(session: Session, store: SessionStore, now: Clock, ttlMs: number = DEFAULT_SESSION_TTL_MS): Session {
	const extended: Session = { ...session, expiresAt: now() + ttlMs };
	store.put(extended);
	return extended;
}

/** Ends a session. Returns false if there was none. */
export function revokeSession(token: string, store: SessionStore): boolean {
	return store.delete(token);
}

import * as assert from "../premise/assert.js";
import type { Tests } from "../premise/assert.js";
import { createMemorySessionStore } from "../src/store/memory-store.js";
import { verifySession } from "../src/auth/session.js";
import { fixedClock, HOUR } from "../util/time.js";
import { makeSession, T0 } from "./support.js";

export const tests: Tests = {
	"verifySession returns null for an expired session": () => {
		const session = makeSession({ expiresAt: T0 + HOUR });
		const store = createMemorySessionStore([session]);
		const expiredClock = fixedClock(T0 + HOUR + 1);
		assert.eq(verifySession(session.id, store, expiredClock), null);
	},
	"verifySession still returns a session that has time left": () => {
		const session = makeSession({ expiresAt: T0 + HOUR });
		const store = createMemorySessionStore([session]);
		const validClock = fixedClock(T0 + HOUR - 1);
		assert.deepEq(verifySession(session.id, store, validClock), session);
	},
};

